// Copyright 2026 Saudi Agentic AI Entrepreneurship Academy contributors. Apache-2.0.
// Prepare: everything the model step needs is decided here, in code.
// The customer's text is data. It is wrapped and never mixed into the instructions.
// Arabic text helpers, the same rules as labs/reference/order_agent/text.py.
function normalise(text) {
  return String(text).replace(/[ً-ْـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
}
function westernDigits(text) {
  const map = '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹';
  return String(text).replace(/[٠-٩۰-۹]/g, (d) => String(map.indexOf(d) % 10));
}
function maskPhone(phone) {
  phone = String(phone);
  return '*'.repeat(Math.max(phone.length - 2, 0)) + phone.slice(-2);
}
const cfg = $('Config').first().json;
const body = $('Webhook').first().json.body || {};
let message = String(body.message ?? '');
if (cfg.normalise_digits) message = westernDigits(message);
const glossary = Object.entries(cfg.glossary || {}).map(([term, meaning]) => `- ${term}: ${meaning}`);
// The instructions name the business and, where the model must pick from a list, carry that list.
// Found on the first run with a real model (21 November 2026): the placeholder reached the model as written,
// and the booking instructions said "the approved list" without giving it.
const services = Array.isArray(cfg.services) ? cfg.services.map((name) => `- ${name}`) : [];
const system = String(cfg.instructions).split('(اسم المنشأة)').join(cfg.business_name || 'المنشأة')
  + (services.length ? '\n\nالقائمة المعتمدة للخدمات (اكتب الاسم كما هو هنا):\n' + services.join('\n') : '')
  + (glossary.length ? '\n\nمصطلحات العملاء:\n' + glossary.join('\n') : '');
const stopped = Boolean(cfg.stopped);
return [{
  json: {
    message,
    account: String(body.account ?? ''),
    ref: String(body.ref ?? ''), // the caller's own id for this message; used by the shadow record
    state: body.state && typeof body.state === 'object' ? body.state : {},
    stopped,
    route: !stopped && cfg.model_mode === 'http' ? 'http' : 'sim',
    model_url: String(cfg.model_base_url || '').replace(/\/+$/, '') + '/chat/completions',
    request_body: {
      model: cfg.model_name,
      temperature: 0,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: `<customer_message>\n${message}\n</customer_message>` },
      ],
    },
  },
}];

// Copyright 2026 Saudi Agentic AI Entrepreneurship Academy contributors. Apache-2.0.
// Simulated model: NOT a language model. It matches the keywords listed under "sim" in the
// Config node, so the workflow runs with no key, no cost and the same result every time.
// It understands far less than a real model. That is its job: it lets you test the limits.
// Arabic text helpers, the same rules as labs/reference/order_agent/text.py.
function normalise(text) {
  return String(text).replace(/[ً-ْـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
}
function westernDigits(text) {
  const map = '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹';
  return String(text).replace(/[٠-٩۰-۹]/g, (d) => String(map.indexOf(d) % 10));
}
function maskPhone(phone) {
  phone = String(phone);
  return '*'.repeat(Math.max(phone.length - 2, 0)) + phone.slice(-2);
}
const cfg = $('Config').first().json;
const text = normalise(westernDigits($input.first().json.message));
const has = (words) => words.some((w) => text.includes(normalise(w)));
const hit = (cfg.sim.intents || []).find(([, words]) => has(words));
const understanding = { intent: hit ? hit[0] : 'unknown' };
for (const [field, options] of Object.entries(cfg.sim.choices || {})) {
  const option = options.find(([, words]) => has(words));
  understanding[field] = option ? option[0] : null;
}
for (const [field, pattern] of Object.entries(cfg.sim.patterns || {})) {
  const match = text.match(new RegExp(pattern, 'u'));
  understanding[field] = match ? (match[1] ?? match[0]) : null;
}
return [{ json: { understanding } }];

// Copyright 2026 Saudi Agentic AI Entrepreneurship Academy contributors. Apache-2.0.
// Decide: template 1, customer service. The oversight table of the template, enforced in code.
// The model only names the intent and the topic. Every answer comes from approved content.
// Arabic text helpers, the same rules as labs/reference/order_agent/text.py.
function normalise(text) {
  return String(text).replace(/[ً-ْـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').toLowerCase();
}
function westernDigits(text) {
  const map = '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹';
  return String(text).replace(/[٠-٩۰-۹]/g, (d) => String(map.indexOf(d) % 10));
}
function maskPhone(phone) {
  phone = String(phone);
  return '*'.repeat(Math.max(phone.length - 2, 0)) + phone.slice(-2);
}
// The model's answer is untrusted: take one JSON object out of it, or nothing.
function readModel(item) {
  if (item && item.understanding && typeof item.understanding === 'object') return item.understanding;
  try {
    const content = item.choices[0].message.content;
    const parsed = JSON.parse(content.slice(content.indexOf('{'), content.lastIndexOf('}') + 1));
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch (error) {
    return { error: 'model_output_unreadable' }; // a model failure must never act on its own
  }
}
const cfg = $('Config').first().json;
const prepared = $('Prepare').first().json;
const understood = readModel($input.first().json);
// One result shape for every template. `level` is the row of the oversight table that applied.
const result = { action: null, level: null, intent: 'unknown', reply_draft: '', handover: null, pending_approval: [],
  notify_staff: [], tool_calls: [], state: {}, log: { account: maskPhone(prepared.account) } };
// Shadow mode (Config `shadow_mode`: true): the agent runs beside the staff and nothing leaves it.
// Decide works on a copy of the workflow's stored data, so no booking or draft is kept, and `done`
// moves everything the agent would have sent, written or asked for under `shadow.would`.
// Reads still happen: the agent cannot say what it would do without looking, so the customer's
// data is processed all the same. The caller files the shadow record; `ref` ties it to the staff's record.
const shadowMode = cfg.shadow_mode === true;
const storedData = () => (shadowMode ? JSON.parse(JSON.stringify($getWorkflowStaticData('global'))) : $getWorkflowStaticData('global'));
const done = (fields) => {
  Object.assign(result, fields);
  if (!shadowMode) return [{ json: result }];
  const { intent, log, ...would } = result;
  return [{ json: { mode: 'shadow', action: 'shadow_observed', level: 'shadow', intent, reply_draft: '', handover: null,
    pending_approval: [], notify_staff: [], tool_calls: [], state: prepared.state, log: Object.assign(log, { shadow: true }),
    shadow: { ref: prepared.ref, would } } }];
};
const handover = (action, level, summary, reply, urgency = 'normal') => done({ action, level,
  handover: { summary, urgency }, reply_draft: reply || 'شكراً لتواصلك. حوّلنا طلبك إلى أحد الفريق وسيتواصل معك.' });
const own = (object, key) => (typeof key === 'string' && Object.prototype.hasOwnProperty.call(object, key) ? object[key] : null);
const INTENTS = ['faq', 'order_status', 'refund', 'cancel', 'discount', 'promise', 'complaint', 'advice', 'human', 'unknown'];
const intent = INTENTS.includes(understood.intent) ? understood.intent : 'unknown';
result.intent = intent;
result.log.intent = intent;
result.state = { greeted: true };
const greeting = prepared.state.greeted ? '' : `أهلاً بك. أنا المساعد الآلي لدى ${cfg.business_name}. اكتب «موظف» في أي وقت للتحدث مع أحد الفريق.\n`;
const say = (text) => greeting + text;

if (prepared.stopped) return handover('stopped', 'stopped', 'المساعد موقوف. كل الرسائل تُحال إلى الفريق.', say('حوّلنا رسالتك إلى أحد الفريق.'));

if (intent === 'faq') {
  const entry = own(cfg.knowledge, understood.topic);
  if (!entry) return handover('handover_not_in_knowledge', 'autonomous', 'سؤال لا جواب له في المحتوى المعتمد.', say('لا أجد جواباً مؤكداً لسؤالك. حوّلته إلى أحد الفريق.'));
  result.tool_calls.push({ tool: 'knowledge_search', input: understood.topic });
  return done({ action: 'answer', level: 'autonomous', source: { topic: understood.topic, approved_on: entry.approved_on },
    reply_draft: say(`${entry.text}\nهل تحتاج شيئاً آخر؟`) });
}
if (intent === 'order_status') {
  const ref = typeof understood.order_ref === 'string' ? understood.order_ref.trim().toUpperCase() : null; // tool input is normalised in code
  if (!ref) return done({ action: 'ask_order_ref', level: 'autonomous', reply_draft: say('فضلاً أرسل رقم الطلب لنتحقق من حالته.') });
  const order = own(cfg.orders, ref);
  if (order && order.account !== prepared.account) { // another customer's order: refused before anything is read
    return done({ action: 'refuse_other_customer', level: 'forbidden', reply_draft: say('عذراً، لا نشارك بيانات طلب مسجّل على رقم آخر.') });
  }
  result.tool_calls.push({ tool: 'order_lookup', input: ref });
  if (!order) return done({ action: 'order_not_found', level: 'autonomous', reply_draft: say(`لم نجد طلباً بالرقم ${ref}. فضلاً تأكد منه.`) });
  return done({ action: 'answer_order_status', level: 'autonomous', reply_draft: say(`حالة طلبك ${ref}: ${order.status_text}.`) });
}
if (intent === 'refund' || intent === 'cancel') {
  return handover('handover_staff_action', 'forbidden_for_agent', `طلب ${intent === 'refund' ? 'استرجاع' : 'إلغاء'}${understood.order_ref ? ` للطلب ${understood.order_ref}` : ''}. لم يُنفَّذ شيء.`,
    say('سجّلنا طلبك وحوّلناه إلى أحد الفريق، وهو من ينفّذه ويتواصل معك.'));
}
if (intent === 'discount' || intent === 'promise') {
  result.pending_approval.push({ action: intent === 'discount' ? 'offer_discount' : 'promise_date_or_exception', level: 'approve' });
  return handover('handover_needs_approval', 'approve', intent === 'discount' ? 'العميل يطلب خصماً.' : 'العميل يطلب موعداً مؤكداً أو استثناء.',
    say('هذا يحتاج موافقة أحد الفريق. حوّلنا طلبك وسيتواصل معك.'));
}
if (intent === 'complaint') return handover('handover_complaint', 'autonomous', 'شكوى. تُقرأ كما وردت.', say('نعتذر عمّا حدث. حوّلنا شكواك إلى أحد الفريق وسيتواصل معك.'), 'high');
if (intent === 'advice') return handover('refuse_advice', 'forbidden', 'سؤال طبي أو قانوني أو شرعي. لم يُجب عنه.', say('لا أستطيع تقديم مشورة طبية أو قانونية أو شرعية. حوّلتك إلى أحد الفريق.'));
if (intent === 'human') return handover('handover_requested', 'autonomous', 'العميل طلب موظفاً.', say('حوّلناك إلى أحد الفريق.'));
return handover('handover_not_understood', 'autonomous', 'رسالة لم تُفهم. تُحال كما هي.', say('لم أفهم طلبك تماماً. حوّلته إلى أحد الفريق.'));
